/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { And, Mul, Or, Q, allargs, anyarg, exactlyonearg, mul, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.assumptions.sathandlers", () => {
  it("allargs(x, Q.negative(x) | Q.positive(x), x*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(allargs(x, Or(Q.negative(x), Q.positive(x)), mul(x, y)))).toBe('(Q.negative(x) | Q.positive(x)) & (Q.negative(y) | Q.positive(y))');
  });
  it("anyarg(x, Q.negative(x) & Q.positive(x), x*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(anyarg(x, And(Q.negative(x), Q.positive(x)), mul(x, y)))).toBe('(Q.negative(x) & Q.positive(x)) | (Q.negative(y) & Q.positive(y))');
  });
  it("exactlyonearg(x, Q.positive(x), x*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(exactlyonearg(x, Q.positive(x), mul(x, y)))).toBe('(Q.positive(x) & ~Q.positive(y)) | (Q.positive(y) & ~Q.positive(x))');
  });
});

describe("sympy/assumptions/tests/test_sathandlers.py", () => {
  it("test_allargs:31", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(allargs(x, Q.zero(x), new Mul([x, y])))).toBe('Q.zero(x) & Q.zero(y)');
  });
  it("test_allargs:32", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(allargs(x, Or(Q.negative(x), Q.positive(x)), new Mul([x, y])))).toBe('(Q.negative(x) | Q.positive(x)) & (Q.negative(y) | Q.positive(y))');
  });
  it("test_anyarg:36", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(anyarg(x, Q.zero(x), new Mul([x, y])))).toBe('Q.zero(x) | Q.zero(y)');
  });
  it("test_anyarg:37", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(anyarg(x, And(Q.negative(x), Q.positive(x)), new Mul([x, y])))).toBe('(Q.negative(x) & Q.positive(x)) | (Q.negative(y) & Q.positive(y))');
  });
  it("test_exactlyonearg:42", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(exactlyonearg(x, Q.zero(x), new Mul([x, y])))).toBe('(Q.zero(x) & ~Q.zero(y)) | (Q.zero(y) & ~Q.zero(x))');
  });
  it("test_exactlyonearg:44", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(exactlyonearg(x, Q.zero(x), new Mul([x, y, z])))).toBe('(Q.zero(x) & ~Q.zero(y) & ~Q.zero(z)) | (Q.zero(y) & ~Q.zero(x) & ~Q.zero(z)) | (Q.zero(z) & ~Q.zero(x) & ~Q.zero(y))');
  });
  it("test_exactlyonearg:47", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(exactlyonearg(x, Or(Q.negative(x), Q.positive(x)), new Mul([x, y])))).toBe('((Q.negative(x) | Q.positive(x)) & ~(Q.negative(y) | Q.positive(y))) | ((Q.negative(y) | Q.positive(y)) & ~(Q.negative(x) | Q.positive(x)))');
  });
});
